-- =====================================================================
-- BORA — 0004: paradas de ônibus reais do DF (OpenStreetMap)
-- Dados © colaboradores do OpenStreetMap, licença ODbL (openstreetmap.org/copyright).
-- Gerado a partir de um export do overpass-turbo (highway=bus_stop no DF).
-- Paradas sem nome no OSM recebem o nome da parada nomeada mais próxima
-- (até 400 m) ou da região. A região é a RA mais próxima (aproximação).
-- As 22 paradas originais continuam (são usadas pelo grafo antigo).
-- =====================================================================

alter table stops
  add column if not exists source      text not null default 'manual',
  add column if not exists has_shelter boolean,
  add column if not exists is_lit      boolean;

on conflict (id) do update
  set name = excluded.name, region = excluded.region, lat = excluded.lat, lng = excluded.lng,
      has_shelter = excluded.has_shelter, is_lit = excluded.is_lit;

update stops set source = 'osm' where id like 'osm\_%';
